<h1>Find Collabs</h1><?php foreach($collabs as $c):?><article class="card"><h2><?=H::e($c['title'])?></h2><p>Host: <?=H::e($c['host_name'])?> · Minimum <?=$c['minimum_file_count']?> files · deadline <?=H::e($c['upload_deadline'])?> · sale through <?=H::e($c['sale_close_date'])?></p><?php if(!$c['membership_status']):?><form method="post" action="/seller/collabs/<?=$c['id']?>/request"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><button>Request to join</button></form><?php else:?><span class="badge"><?=H::e($c['membership_status'])?></span><?php endif;?></article><?php endforeach;?><?php if(!$collabs):?><p>No open collabs are joinable.</p><?php endif;?>
